-- Services and prices are intentionally branch-specific. Existing service rows
-- remain for historical booking records, but only rows with branch_id are public.
alter table public.services
  add column if not exists branch_id text references public.branches(id) on delete cascade;

create index if not exists services_branch_price_idx on public.services (branch_id, price);

on conflict (id) do update set
  branch_id = excluded.branch_id,
  name = excluded.name,
  description = excluded.description,
  price = excluded.price,
  duration_minutes = excluded.duration_minutes;

delete from public.barber_services
where barber_id in ('kai-loc', 'linh-color', 'son-line', 'minh-fade', 'ryo-beard', 'bao-crop', 'hieu-wave');

